          "白登之围使汉廷上下认清现实：天下初定，民生凋敝，国力难以与控弦三十馀万的匈奴争锋。刘邦采纳刘敬之策，遣其使匈奴，缔结和亲之约。刘敬向高祖陈说利害：以汉家嫡长公主妻冒顿，厚加馈赠，则「冒顿在，固为子婿；死，则外孙为单于」，未闻外孙敢与外祖抗礼者，可渐臣之。汉高祖八年（前199年），刘敬奉命出使，往返斡旋，和亲之议遂定。",
          "汉高祖九年（前198年），刘敬护送汉宗室女为公主嫁冒顿单于，汉朝每年赠送絮缯、酒米、食物各有定数，约为兄弟之国，互通关市。自此，和亲成为汉初数十年对匈基本国策，以宗室女嫁单于、岁赠币帛换取边境安宁。此策虽未能尽绝匈奴侵扰，却为文景之世休养生息赢得数十年安定，积蓄了国力，至汉武帝元光二年（前133年）马邑之谋，汉朝才转守为攻，揭开全面反击匈奴的序幕。"
