    interpretation: "白登之围是汉匈关系史上的转折点，也是中原王朝与北方游牧政权力量消长的缩影。就军事而言，冒顿单于以匿精壮、示羸弱之计诱敌深入，再以四十万骑兵机动合围，将游牧骑兵的速度与集中优势发挥到极致；刘邦舍弃步兵主力、轻骑突前，犯了兵分力散的大忌，一旦陷入重围，车步之阵在冰原旷野上无法与骑兵周旋。就国力而言，汉初「自天子不能具醇驷，而将相或乘牛车」（见《史记·平准书》），经济凋敝，无法支撑长期对匈奴的大规模战争。白登之围以最直接的方式宣告：以战止战在当时并不可行。和亲之策的本质，是以经济让步换取战略时间，用币帛、关市与婚姻羁縻匈奴，为文景之治的休养生息和汉武帝时代的全面反击奠定了物质与制度基础。汉朝由此在屈辱中积蓄力量，在隐忍中完成战略转换，这或许正是白登之围留下的最大遗产。",
