    interpretation: "班超经营西域之成功，在于以极小成本维系汉廷对西域的控制。其所恃者，非汉军之多，乃汉廷之威信、诸国之利害与班超个人之胆略。东汉初定，户口凋耗，光武、明、章之世，皆无意也无力大举远征；班超以三十六人起家，借诸国之兵攻诸国之敌，以夷制夷，此为汉廷经略西北成本最低之方式。其守疏勒、拒贵霜、平焉耆，使匈奴失其右臂，丝路复通，商旅东至洛阳，西达葱岭之外，甘英临西海之行，更为汉人地理知识之所未及。然超卒不过数年，西域复叛，足见其经营之成，系于一人之威望，而未深植于制度；都护之设虽复，屯田之兵不充，汉廷于西域之控制，终随国力消长而进退。班超之业，上承张骞凿空，下启汉魏西域之治，其个人英雄色彩之浓，于两汉外臣中无出其右者。",
