          "《后汉书》记其结局仅数语，而字字如见：「伦初受窦后讽旨，枉陷宋贵人，帝敕使自致廷尉。伦耻受辱，乃沐浴，整冠衣，饮药而死。国除。」蔡伦时已年逾六旬，历事明帝、章帝、和帝、殇帝、安帝五朝，出入宫禁四十余年，封侯食邑，典校经传，一旦追究旧案，竟无一人回护。沐浴整冠衣而后饮药，是汉代士大夫临死全身的旧仪，蔡伦以刑余之人而行此礼，可见其视耻辱甚于死生。龙亭侯国随之除废，三百户食邑一朝尽去。",
          "建光之变，实为东汉宫廷政治的一个缩影。自和帝时郑众助帝诛窦宪，宦官始得封侯，预政日深；其后孙程、曹腾之流接踵而起，终成汉末乱局。蔡伦身处这一潮流的起点，以才技进身，以罪案见逼，荣枯生死，皆系于皇权之一怒一喜。他受窦后讽旨时不过一小黄门，纵有不愿，亦难抗中宫之命；及安帝追论，又无人替他分说当年情由。小人物被卷入旋涡而不得脱身，正是东汉宫禁斗争的常态，纲纪陵夷之际，个人的才干与清白，往往都无足轻重。"
