    interpretation: "蔡伦的一生，是才技与权谋、功业与罪案纠缠的一生。他以一介刑余之人，历事五朝，任尚方令则器械精工为后世法，造纸则造意开新，皆见其心思才干；然受窦后讽旨参与罗织宋贵人，又是其难以洗刷的污点。此中关键，在于东汉宦官之地位本系于皇权与后宫的恩威：奉旨考案时身不由己，追论旧案时亦无人回护。造纸一事亦当如是观：西汉已有麻纸，技术演进非自蔡伦始；蔡伦的贡献，在于以树肤、麻头、敝布、鱼网等贱料，使纸可批量、廉价地造出，由是取代简帛、行于天下，这是集大成而开新局的质变。观其身死国除而纸法长存，正见个人荣辱如朝露，而技术之功泽被千秋。",
