    interpretation: "察举制之深意，在于将选官之权由血统收归国家，由地方推荐与中央考试分掌。汉初功臣垄断仕途，高祖求贤诏一发，布衣贤士始有登进之阶；武帝定孝廉为常科，复兴太学，经术遂为仕进正途，士人群体由此形成，儒学亦藉选举以定于一尊。阳嘉改制限年试经，以考试约束推荐，已开科举以考取士之先声。然察举根本在推荐，举主与被举者结为恩主故吏之私恩，权力网络盘根错节，日久必为门阀劫持，东汉民谣与西园卖官即其明证。故九品中正行而门第定，至隋唐废中正、重考试，科举出而察举之精神始得复续。",
