    interpretation: "陈平之奇，不在战场决胜，而在审机于帷幄、转危为安于危难之间。其学出黄老，其术则阴谋与阳谋互用：反间、佯降、矫封、伪游、厚赂，皆《孙子兵法》所谓不战而屈人之兵之流亚也。高祖雄猜，功臣多诛，而平以智全；吕后酷烈，王陵面折见黜，平以韬晦自保而徐图之。其于惠帝、高后之际，不争一日之直，而收定刘之实，正其自言之明验。然平亦自知「多阴祸」，子孙遂微。此非果报之谈，乃谋国与谋身难以两全之理：阴谋者，事成而不居其名，名不居则恩赏不显，恩赏不显则后嗣无援。此平之所以兴，亦平之所以微也。司马迁论平「倾侧扰攘楚魏之间，卒归高帝，常出奇计，救纷纠之难，振国家之患」，又赞其「以安宗庙，定刘氏后，可谓良相」。汉初功臣，萧何、张良、韩信并称三杰，而平历四朝，终始无伤，其明哲保身与深谋远虑，实兼众长而有之。",
