    interpretation: "楚汉之争之结局，非尽如项羽所言「此天之亡我，非战之罪也」，实为两种政治路线与用人之道之争。项羽以武力分封十八路诸侯，欲复战国列国并立之局，然所封非亲即故，赏罚不明，田荣、陈馀、彭越等实力派旋即叛之；又屠咸阳、杀子婴、烧秦宫室，尽失秦民之心。刘邦则承秦制而行郡县，入关时约法三章、悉除秦苛法，先收民心；萧何留守关中，镇国家、抚百姓、转漕馈饷，使前线虽屡败而根基不动；张良运筹帷幄，陈平数出奇计，韩信连兵百万、战必胜攻必取。刘胜项败，其要在用人与得民：信赏必罚、能听善策，故三杰为之用；项羽有一范增而不能用，刚愎自专，终至众叛亲离。汉之立国，上承秦制，下开四百年大一统之局，郡县与封国并行、三公九卿之制多为后世所因，奠定了此后中国政治制度的基本格局。",
