          "永康元年（167年）六月，桓帝下诏大赦天下，党人二百余名获释放归乡里。然诏书明令「禁锢终身」，即终身不得入仕为官。李膺归乡之日，士林沿途迎候，车骑塞路，其声望反高于入狱之前。天下士人皆以党人为荣，而宦官衔恨益深，伺机而动。同年十二月，桓帝驾崩，灵帝刘宏以藩王入继大统，年方十二，窦太后临朝称制，外戚与宦官之争再起，新的政治风暴正在酝酿。"
