          "建宁元年（168年）春，灵帝即位，年方十二，窦太后临朝称制。窦武以太后之父拜大将军，陈蕃复为太尉，与司徒胡广共录尚书事。窦、陈二人同心辅政，起用第一次党锢中被禁锢之士，李膺、杜密等虽未复官，其门生故吏多获拔擢，朝政颇有振兴之望。窦武、陈蕃以宦官专权乱政，密谋诛灭曹节、王甫等。窦武先奏请太后诛宦官管霸、苏康等，太后从之，然对曹节、王甫等，太后犹豫不忍，久未裁断。",
          "建宁元年九月，窦武、陈蕃之谋泄露。窦武上奏太后请诛宦官，奏章留中未发，宦官朱瑀窃见之，大惊，星夜告知曹节、王甫。曹节等先发制人，矫诏收捕窦武。陈蕃闻变，率属从官八十余人拔刀入承明门，欲救太后，遇王甫率兵拦截，陈蕃拔剑叱之，终因寡不敌众被擒，即日遇害，夷三族。窦武驰还军营，集兵抵抗，然其部曲纷纷溃散，窦武走投无路，自杀身亡，亦被夷三族。窦太后被迁于南宫。",
