          "张俭虽逃，大狱已起。宦官集团借机穷治党人，李膺、杜密、范滂等名士皆在搜捕之列。李膺时居颍川乡里，闻官差将至，自投于官，入狱后遭严刑拷掠，死于狱中。杜密闻变，自杀身亡。范滂被收捕时，与母诀别，其母勉之曰：「汝今与李、杜齐名，死亦何恨！既有令名，复求寿考，可兼得乎？」范滂再拜而辞，慷慨就死。此次党锢，党人死于狱中者百余人，妻子徙边，其门生、故吏、父兄五属，皆免官禁锢，株连者六七百人。",
