    interpretation: "党锢之祸的本质，是东汉外戚、宦官、士大夫三方政治势力的最终摊牌。宦官以皇权为护符，士大夫以清议为武器，双方势同水火。桓帝、灵帝之所以站在宦官一边，非不知党人之冤，而是恐惧士人结党会动摇皇权。然杀士人易，毁士心难。两次党锢，不仅诛杀了李膺、范滂等一代名臣，更摧毁了东汉察举选官赖以运行的根基。此后朝廷用人，不问才德，唯问门第与逢迎；士人报国无门，或投靠军阀，或遁入玄学。黄巾乱起，朝廷竟无可用之臣，被迫解党禁以应急，然为时已晚。汉室之亡，实亡于党锢。",
