    interpretation: "董仲舒的历史地位，关键不在官位，而在他回答了新兴大一统帝国的三个根本问题：其一，政权合法性——以天人感应、君权神授之说，为皇权罩上神圣光环，同时以灾异谴告为约束，使君权既神圣又不可恣肆；其二，统治秩序——以三纲五常配天道，将伦理纲常上升为宇宙法则，为社会等级提供恒久依据；其三，人才与教化——请立太学、举孝廉，使儒生经由学官与察举进入官僚体系，获得制度性力量。班固论之最切：「推明孔氏，抑黜百家，立学校之官，州郡举茂材孝廉，皆自仲舒发之。」然须辨明者：武帝朝「罢黜百家」并非尽废诸子，朝廷实「霸王道杂之」，文法吏与儒生并用；仲舒本人因灾异下狱当死，亦见以天道制衡皇权之脆弱。仲舒真正的贡献，是把儒学改造成兼具宇宙论论证与制度方案的官方学说，由此奠定的「儒学与权力双向塑造」之格局，支配了中国此后两千年的政治文化。",
