          "袁绍怒而渡河追击，遣大将文丑率五六千骑追蹑曹军。曹操于延津南坡设伏，令士卒解鞍放马，弃辎重于道。文丑骑兵争抢辎重，阵势大乱；曹操率六百余骑兵纵击，大破之，斩文丑。先是沮授劝袁绍持重缓进，分兵屯守延津，绍不听。颜良、文丑皆河北名将，相继授首，袁军锐气大挫，曹操军心始安。然两军众寡之势未改，袁绍仍步步南压。",
