          "乌巢火起，袁军大乱，曹操亲冒矢石督战，士卒殊死搏斗，淳于琼等不能支，退守营垒待援，终被曹军斩杀，袁军粮屯尽数焚毁。袁绍闻乌巢失火，不急救援，反遣轻骑往援，而命张郃、高览率重兵强攻曹操官渡大营，欲以拔营为功。张郃等攻营不克，又闻淳于琼兵败被斩，惧罪于郭图之谮，遂焚攻具，率众降曹。袁军粮秣尽失，十万之众一夜溃散。",
