          "汉三年（前204年），汉王使郦生往说齐王田广，广听，留郦生纵酒，撤守备。韩信闻之，夜度平原，袭破齐历下军，遂至临淄。齐王以为郦生卖己，乃烹郦生，引兵东走高密，求救于楚。项王使龙且将兵二十万救齐，与信夹潍水而阵。信夜令人为布囊盛沙，壅水上流，引军半渡，龙且起兵迎击，信佯不胜还走；龙且喜曰：「固知信怯也。」遂渡水追之。信使人决壅囊，水大至，龙且军大半不得渡，信急击，杀龙且，虏齐王广，尽定齐地。潍水半渡之计，遂为兵法范例。",
          "韩信既定齐，使人言于汉王曰：「齐伪诈多变，反覆之国也，南边楚，不为假王以镇之，其势不定，愿为假王便。」是时汉王困于荥阳，得书大怒，骂曰：「吾困于此，日夜望若来佐我，乃欲自立为王！」张良、陈平蹑汉王足，因附耳语曰：「汉方不利，不如因而立之，使信自为守；不然，变生。」汉王悟，因复骂曰：「大丈夫定诸侯，即为真王耳，何以假为！」乃遣张良立信为齐王，征其兵使击楚。",
