    interpretation: "韩信以布衣登坛，数年之间，定三秦、破魏赵、灭齐楚，垓下一战而定天下，其功为汉初功臣之首，故与张良、萧何并称「汉初三杰」。然功高震主，势必难容。汉初行郡县与分封并行之制，异姓诸侯王据地拥兵，为朝廷心腹之患；刘邦即位后，燕王臧荼、韩王信、梁王彭越、淮南王英布次第诛废，韩信之王楚，首当其冲。就信本人而言，求封齐王已兆猜忌，居齐握重兵而拒蒯通三分之计，见其忠于汉而拙于自全；及至云梦被执、钟室伏诛，「狡兔死，良狗烹」遂成千古功臣之叹。太史公论曰：信若学道谦让，不伐己功，不矜其能，则汉家之勋可比周、召、太公，后世血食矣。其背水阵、潍水半渡、明修栈道暗度陈仓，皆为后世兵法楷模，「兵仙」之名，良有以也。",
