    interpretation: "《汉书》之深意，首在断代为史。司马迁以一人之身通古今之变，成一家之言；班固则以王朝兴衰为断限，专记西汉二百三十年事，使一代制度典章、治乱得失粲然可考。后世正史自《三国志》以下，皆循断代之体，非通史之不能，乃王朝之所需。盖修史之权归于朝廷，史书即为王朝正统之证明。班固因私撰获罪、因奉诏成书，其一身之遭际，实开官修国史之端，唐宋以后设馆修史、宰相监修，皆肇基于此。其次在志。《艺文志》存先秦西汉典籍之目，《地理志》备天下郡国户口之数，《食货志》详一代经济之制，皆后世所取法。其文赡雅，叙事有法，范晔称其「不激诡，不抑抗」。然其书尊汉室、宗《春秋》之义，论赞多本经义，不及《史记》之疏荡有奇气，此亦官修与私撰之别。要之，《汉书》创断代之体、垂官修之制、开专门之学，与《史记》并峙，而用法不同，各极其胜。",
