          "推恩之外，又有酎金之罚。元鼎五年（前112年），郊祭，列侯献酎金助祭，武帝使少府严察成色斤两，不如法者辄夺爵削籍，一次夺侯者一百六人，丞相赵周坐不举奏，下狱死。赵周之死，实为武帝立威于列侯。经此二事，汉初所封功臣列侯十去其七，诸侯王唯衣食租税，不与政事，大国不过十余城，小侯不过数乡，汉初郡国并行之患遂绝。列侯子孙虽存爵士，不得预郡国治民之权，宗藩之势自此消弭。",
