    interpretation: "《淮南子》之编撰与进献，须置于汉初政治与学术双重变局中理解。黄老之治经文、景而大行，诸侯王坐镇一方，多招宾客，淮南国据楚地人文之盛，遂成学术重心；然吴楚七国之乱后，中央削藩日急，诸侯唯衣食租税，刘安以宿王之尊处疑忌之地，其献书既是学术陈情，亦是政治自明。书以道家为宗、兼采百家，实为先秦诸子作一总结，亦为黄老之治留下最完备的理论文本。武帝终未用其说，独尊儒术自此而兴，则《淮南子》成书进献之年，正两种治道交替之关口。刘安身死国除，书不因人废，其神话、科技与思想史料，补正史之阙，存先秦之学，为中国文化典籍中不可废者。",
