    interpretation: "黄巾起义是中国历史上第一次以宗教组织形式发动的大规模农民起义。张角以符水治病聚众，十余年间编三十六方、众至数十万，其组织之严密远超秦末陈胜、新末赤眉。起义虽仅十月而败，却直接催生两大后果：其一，汉廷被迫解除党锢、下放军权，州牧制度使地方军政合于一身，东汉大一统局面瓦解，群雄割据由可能变为现实；其二，太平道以「黄天」代「苍天」，本于五行相生之说，开后世民间宗教起义之先河。皇甫嵩、朱儁虽以战功定乱，功臣旋即见忌；董卓等边将坐大，终至东汉名存实亡。故史家论曰：黄巾未亡汉室，而汉室已自亡。",
