    interpretation: "《九章算术》的深层性格，是「以术驭题、以用为归」。与古希腊欧几里得《几何原本》的公理演绎不同，它不重命题证明，而把计算程序化：每「术」都是一条可逐步执行的算法，从问、答到术，构成「问题—算法—答案」的开放结构。这种性格源自其成书土壤——全书由田亩、赋税、漕运、工程、测量的政务需求塑造，删补者张苍、耿寿昌都是掌度支的计臣，而非纯粹学者。它的世界领先之处，如分数四则、负数加减、开平方开立方、联立方程消元、勾股测量，无一不是从实务中提炼出的通用方法。正因如此，它不是一部封闭的著作，而是一条传统：刘徽注以「析理以辞」为之立论，李淳风奉敕为之释义，秦九韶、朱世杰沿其方程开方一路推至高次方程与四元术。它奠立的不仅是东亚数学千余年的根基，更是一种以算法为核心的数学思维——这一思维与今日程序化计算遥相呼应。",
