    summary: "更始元年（23年）六月，王莽遣司徒王邑、司空王寻统州郡兵四十二万，号称百万，南下围攻昆阳（今河南叶县）。城中绿林守军仅八九千人，太常偏将军刘秀率宗佻、李轶等十三骑夜出求援，旋收郾、定陵之兵，自将敢死士三千人自城西冲阵，阵斩王寻。会暴雨大作，屋瓦皆飞，莽军大溃，伏尸百余里，溺死滍水者以万计，水为之不流。此役一举摧毁新朝最后的野战主力，天下郡县望风归降更始；同年九月王莽败死于长安渐台，新朝覆灭。昆阳之战实为新汉兴亡的转折，亦为刘秀开创东汉帝业奠基的第一战。",
    background: "王莽自建国元年（9年）代汉立新，托古改制：货币数度改铸，王田、私属之令纷出，又轻启边衅，四夷兵连。法令琐碎，动辄得罪，农商失业，米价腾贵，民怨沸腾。天凤、地皇之际，关东连遭旱蝗，饥民相食，怨气盈路，天下思乱，往往相聚为盗。新朝根基既毁，所可恃者唯倾国之兵。地皇三年（22年），荆州大饥，新市人王匡、王凤聚饥民入绿林山，号「绿林兵」；南阳蔡阳人刘縯、刘秀兄弟为汉宗室之裔，亦起兵舂陵，号「舂陵兵」，与新市、平林、下江诸部合纵，转攻城邑，声势日盛。地皇四年（23年）二月，绿林诸将立刘玄为帝，建元更始，复汉旗号，拜刘縯为大司徒，刘秀为太常偏将军。更始传檄州郡，王莽闻之大惧，决意倾天下之兵，期于一举荡平。",
