    interpretation: "李广终身不侯，非尽天命，实制度与战局使然。汉家军功，以斩捕首虏盈论为差，而广一生所将，多为寡敌众、苦战突围之局，杀伤相当则军功自如，无赏可录。马邑无功、雁门被俘、右北平被围，三役皆以失期、覆军、无果结案，非将之不勇，乃势之不利。至武帝世，战争由守边御寇变为远出塞外、以骑兵大兵团寻歼匈奴主力的机动作战，所重者在长途奔袭、深入漠南漠北之协同调度，而广行军无部伍行阵、不习文书节度，其旧式边将之风，渐与新战法相违。加以外戚近幸骤贵，贵戚拥精兵，宿将居其下，军中进退多不由己。司马迁以广之遭遇，寄身世之悲，遂使「李广难封」超越个人荣辱，成为后世怀才不遇者共有的精神符号。",
