    summary: "刘彻（前156—前87），汉景帝第十子，七岁立储，十六岁即位，在位五十四年，西汉第七位皇帝。其内颁推恩令、置十三州部刺史、建中朝抑相权，彻底解决诸侯坐大之患；表章六经，立太学、行察举，改正朔、封泰山；盐铁官营、统一五铢、均输平准，尽收财权于中央；外遣卫青、霍去病三击匈奴，命张骞凿空西域，置河西四郡，拓土南越、西南夷、朝鲜。晚年穷兵黩武，征和二年巫蛊之祸逼死太子刘据，四年下轮台诏罪己，转与民休息。后元二年崩，葬茂陵，谥孝武，庙号世宗。其立政立制，奠定此后两千年帝制中国的疆域与制度骨架。",
