          "元光元年（前134）冬十一月，初令郡国举孝廉各一人，察举岁举成为定制，选官之权尽归中央。元封元年（前110）封禅泰山，太初元年（前104）改正朔，用夏正，以正月为岁首，色尚黄，数用五，官名印章皆更。意识形态、教育、选官、历法、祭祀全面整备，儒术与王朝统治深度绑定，士大夫阶层由此形成。太学弟子员至成帝时增至三千人，东汉更达三万，影响两千年。"
