          "连年征伐耗费巨万。元狩四年（前119）漠北之战，斩捕首虏之士受赐黄金二十余万斤，赏赐五十万金，府库大空，财用不足。武帝遂以商贾之术治国用：以东郭咸阳、孔仅为大农丞，领盐铁事，桑弘羊以计算用事侍中。元狩四年起行盐铁官营，募民自费煮盐，官给牢盆；铁器官铸，敢私铸铁器、煮盐者钛左趾，没入其器物。元鼎三年（前114）令民告缗，中家以上大抵破，杨可告缗遍天下，杜周治之，狱少反者。",
