    interpretation: "汉武帝一朝的政治逻辑，可概括为「外儒内法，霸王道杂之」：以儒家为意识形态与选官标准，以法家手段行集权之实，内朝、刺史、推恩、盐铁皆为其中环节。其成就在于把汉初郡国并行、清静无为的妥协型体制，改造为中央集权、国家动员能力空前的大一统帝国，并奠定儒家正统、汉地基本版图与丝绸之路，「汉人」「汉族」之名即由此流传。代价同样沉重：征伐四夷、兴建宫室使海内虚耗，户口减半，关东流民聚而为盗；巫蛊之祸更使汉家元气大伤。难得的是，他以轮台诏罪己，改弦更张，使西汉免蹈秦亡覆辙，得以再续百年。班固以「雄才大略」许之，又惜其不能守文景之恭俭以济民，可谓定评。",
