    interpretation: "汉文帝的历史意义，在于以「不折腾」成就大治。他入继大统时，内有功臣拥立之功、外有诸侯宗室之虑，却以宋昌、张武收兵权于即位之夜，以赏赐安周勃、陈平之心，数年之间，周勃就国、陈平去世，功臣集团自然消解，未兴大狱而皇权独尊。其治国，以黄老无为为表，以儒家具文为里：籍田亲耕，示重农之本；除诽谤妖言，广直言之路；除肉刑、除收孥，合于「胜残去杀」之仁。经济上，田租自十五税一而三十税一，乃至全免，算赋、徭役迭减，使秦末凋敝之天下，数十年间「粟支数年」。对匈奴，和亲与备边并行，细柳之营见其武备不弛，而不轻启战端，以天下初定、民力未苏为本。与儿子汉景帝共同造就的「文景之治」，奠定了汉武帝时代强盛的物质与制度根基，更为后世树立了恭俭宽仁的帝王典范。",
