    summary: "汉献帝刘协（181—234），东汉末代皇帝，汉灵帝次子，母王美人。中平六年（189）九月，董卓废其兄弘农王辩而立之，帝年九岁，自此政柄不在宫掖。在位三十一年间，先值董卓、李傕、郭汜之乱，兴平二年（195）东归洛阳，建安元年（196）为曹操迎至许都，天子之尊渐成曹氏号令天下的旗号。建安五年衣带诏败露，伏皇后亦于建安十九年遇害。延康元年（220）十月禅位于魏王曹丕，东汉统绪至此断绝，汉室四百年天下结于其手。受封山阳公十四年，食邑万户，位在诸侯王上；青龙二年（234）薨于山阳，年五十四，魏明帝素服发哀，以天子礼葬于禅陵，追谥孝献皇帝。",
    background: "东汉自和帝以降，皇帝多幼年即位，母族外戚与宫中宦官轮番秉政，皇权渐成虚器。和帝十岁践祚，窦氏、邓氏、梁氏、何氏相继专朝；宦官郑众、孙程、单超、曹节、王甫、张让等迭起把持禁省，外戚宦官百年拉锯，朝纲屡仆。至桓、灵之世，党锢再起，士大夫横遭禁锢；中平元年（184）黄巾事起，朝廷纳宗室刘焉之议，改刺史为州牧，地方军政大权遂落州郡之手。灵帝刘宏宠何皇后，皇子辩以嫡长立；王美人生协，未几为何皇后鸩杀，协由祖母董太后抚养。灵帝心属协，然惮于何进之势，久未定储。中平六年四月灵帝崩，辩即位，何进与张让等相攻。何进召并州牧董卓入京，反为宦官所杀，袁绍勒兵尽诛中常侍。董卓乘乱而入，以兵威废辩为弘农王，立陈留王协为帝。汉室仅存的名分，自此落入武人之手。",
