    interpretation: "刘协之悲剧，非一人之昏愚，而是汉家制度积弊之总爆发。外戚与宦官的百年拉锯，使皇权沦为宫闱斗争的战利品；黄巾乱后改州牧为实任，朝廷又自弃地方兵柄，于是董卓以并州之兵入京，李傕、郭汜以凉州之众乱政，曹操以兖豫之势奉迎天子——皇帝愈是颠沛，军阀愈是坐大。东归之途、衣带之诏、伏后之死，皆证明「挟天子以令不臣」之下，天子只剩名号。曹丕以禅让代汉，形式上是上古揖让之古礼，实质是武力的合法化包装，却为后世数百年篡代模式立下范本；司马氏代魏、刘裕代晋，无不效此故事。而山阳公得以善终、以天子礼葬，亦为历代亡国之君少见之结局。",
