    interpretation: "光武中兴之深意，不在恢复汉室之名，而在再造一统之实。西汉自元、成以后，外戚擅权，王莽乘隙而入；刘秀以宗室疏属崛起布衣，凭昆阳一战摧莽，持节河北另开局面，终成帝业，可见其成功实兼时势与人事。其治国以柔道，退功臣进文吏，使云台诸将得保首领，较之汉高祖之诛戮功臣，更见节制；尚书台权重、三公府虚，皇权自此更趋集中。度田令虽遭豪强反弹，然检核户口、释放奴婢、裁并州县，使流民著籍、奴婢归良，国家编户与赋役基础由此奠定。后世论者以光武与汉高祖并称，虽功业稍逊，然其宽厚柔克、善始令终，实为三代以下帝王所罕见。",
