    interpretation: "班固《汉书·宣帝纪》赞曰：「孝宣之治，信赏必罚，综核名实，政事、文学、法理之士咸精其能，至于技巧、工匠、器械，自元、成间鲜能及之，亦足以知吏称其职，民安其业也。」此非虚誉。宣帝起于缧绁，长于闾巷，知民间之疾苦，故其施政不务高论，唯求实效：察吏以殿最，恤民以租赋，驭边以威德，论经以折中。其「霸王道杂之」一语，道破汉家制度之精髓——外任德教以收人心，内任法术以核名实，二者相辅，遂开昭宣中兴之局。设西域都护，则张骞之业始成定制；受匈奴臣服，则百年边患暂息。然以刑名绳下，则宽厚之风渐减；以威权防外戚，而元、成以后外戚复盛，终成王莽之祸。观宣帝之治，当察其得，亦不可忽其所伏。",
