      {
        heading: "夜梦金人，白马西来",
        paragraphs: [
          "佛教传入中国，最著名的故事是「明帝求法」。《后汉书·西域传》记载：明帝梦见一个高大金人，头顶光明，醒来以问群臣，有人答「西方有神，名曰佛，其形长丈六尺而黄金色」。于是明帝遣郎中蔡愔、博士弟子秦景等出使天竺，问佛道法，并在中原图画佛像。使团行至大月氏，遇沙门摄摩腾、竺法兰，永平十年（67年）与二沙门同返洛阳，以白马驮载佛经及释迦立像。永平十一年（68年），明帝敕建寺院于洛阳雍门外，以驮经白马为名，是为白马寺——中国第一座官办佛寺，被后世奉为中国佛教的「祖庭」。",
          "不过，「夜梦金人」之事，自宋代起即有学者质疑其真实性，近现代学界亦多认为梦境细节或为后世附会。但佛教于两汉之际经西域传入中原、永平前后汉廷与佛教发生接触，是学界主流共识；明帝遣使建寺的记载，正反映佛教在此时由民间信仰升格为朝廷承认的宗教。最早崇奉佛法的是皇室宗亲：楚王刘英「晚节更喜黄老学，为浮屠斋戒祭祀」，明帝不但不加干涉，还下诏嘉许其「尚浮屠之仁祠，洁斋三月，与神为誓」——这是正史中关于中国人崇佛的最早记录。",
          "永平十三年（70年），楚王英被告发谋反，朝廷穷治其狱，株连者数千人，自京师诸侯、州郡豪杰乃至天下名士，被刑讯者甚众。案中牵出的方士、巫医、浮屠之名，说明早期佛教在中国是依附于黄老道术、神仙方术传播的，时人视佛如黄帝、老子，求的是祈福延年。白马寺初建，僧侣也主要以译经行法事为务。撇开神异色彩，明帝一朝实为佛教中国化的起点：从宫廷到藩国，从译经到奉祀，一种外来宗教自此在中土生根，数百年后蔚为大观，深刻改变了中国的哲学、艺术与民间生活。"
        ]
      },
      {
        heading: "凿空西域，重张都护",
        paragraphs: [
          "自王莽代汉、西域断绝，匈奴乘虚而入，重征诸国赋税，北匈奴骑兵时寇河西，敦煌、武威一带不得安枕。明帝即位后志在断匈奴右臂，恢复西汉旧业。永平十六年（73年），他分兵四路出击北匈奴：窦固、耿秉出酒泉，大败呼衍王于天山，追至蒲类海，取伊吾庐地，置宜禾都尉屯田，打开通往西域的大门。同年，明帝又遣假司马班超与从事郭恂出使西域。班超在鄯善国以「不入虎穴，不得虎子」的胆气，率三十六人夜袭北匈奴使团，鄯善王震服，纳子为质；随后于阗王杀匈奴使者归汉，疏勒、车师相继来附，西域南道基本归顺。",
          "永平十七年（74年），明帝作出重大决定：复置西域都护府，以陈睦为都护，耿恭为戊己校尉屯车师后王部金蒲城，关宠为戊己校尉屯前王部柳中城。这是自王莽始建国年间西域都护李崇败没后，中原王朝时隔六十余年再度恢复对西域的正式管辖，天山南北重归汉家旗帜。丝路复通，西域诸王侍子云集洛阳，东西商旅往来不绝；明帝又遣使大宛、安息，西方物产经河西输入内地，东汉国势达于极盛。",
          "然而局面陡转。永平十八年（75年），明帝驾崩，北匈奴趁机反扑，焉耆、龟兹攻杀都护陈睦，耿恭被围于疏勒城。耿恭率数百人坚守数月，粮尽食铠弩筋革，凿山为井，誓死不降；建初元年（76年），汉军范羌率两千人冒雪驰援，迎耿恭东归，入玉门关时仅余十三人，「十三将士归玉门」由此千古流传。西域都护一度罢废，但班超留驻疏勒，以三十六人纵横捭阖，章帝、和帝两朝终于重定西域，永元三年（91年）班超任西域都护。明帝时代的经略，为此后班超三十一年西域功业奠基，也确立了中原王朝经营西域的基本范式。"
        ]
      }
