    interpretation: "明帝之政，承建武而更严。光武以柔道得天下，明帝以严察理天下，非禀赋之异，乃时势使然。东汉立国依托豪强，功臣宿将、外戚宗室、藩王列侯三股势力盘根错节，若听任膨胀，必重蹈西汉末年外戚倾覆之辙。故明帝以刑律绳百官，以成命抑外戚，以铁腕治宗室，将权柄收归天子一人。其结果，是「断狱得情，号居前世十二」的刑清之治，也是朝廷上下悚栗、政务伤于苛碎的代价。恰在此时，佛法东来，为这座严整帝国的士人开启一扇精神之门；西域重开，则将中原影响力再度推向塔里木盆地。永平之政上承建武、下启明章，是东汉国力的顶点，也是王朝由开基转向守成的关键。",
