    summary: "汉高祖刘邦（前256年—前195年，生年一说前247年），字季，沛县丰邑中阳里人，西汉开国皇帝。秦末起兵于沛，率先入关，约法三章，深得民心；鸿门宴后受封汉王，经五年楚汉战争击败项羽，前202年称帝，定都长安，建立汉朝。在位期间行郡国并行之制，轻徭薄赋，与民休息；又翦除异姓王，斩白马立盟「非刘氏而王，天下共击之」，奠定汉室四百年基业。他出身农家，起于亭长，是中国历史上第一位由平民登上帝位的皇帝，其制度创设与用人格局，深刻塑造了此后两千年帝制中国的政治传统。",
