    interpretation: "刘邦是中国历史上第一位「布衣天子」，其一生恰是秦末社会巨变的缩影：以亭长起兵，三年灭秦，五年胜楚，八年而成帝业。论武功远不及项羽，谋略不及张良，治国不及萧何，统兵不及韩信，其胜在于能用人、能听言、能与天下同利。项羽以楚国贵族身份迷信武力，分封十八路诸侯，实开历史倒车；刘邦则全盘继承秦的郡县、律令、朝仪、赋税制度，所谓「汉承秦制」，同时以郡国并行作过渡，分封同姓王以屏藩皇室，换取政权初创时期的稳固。他翦除异姓王、立白马之盟，将「家天下」与「功臣共治」结合，遂奠汉室四百年之基。其轻徭薄赋、与民休息之策，使凋敝社会迅速恢复，开文景之治先声。上承秦制、下启汉武，刘邦所定的制度与格局，深刻塑造了帝制中国的基本形态。",
