    interpretation: "汉初制度之弊，在于郡国并行使军权、财权下移，宗藩与天子势成水火。文帝以宽柔徐图，贾谊「众建诸侯」之策尚待时日；至景帝则一以法度刀锋直取其地，先削后战，以战促削。七国之乱三月而定，其捷正在于吴楚联军顿于梁之坚城，而周亚夫坚壁断粮，庙算先定；亦因诸侯号令不一，民心不附。司马迁论曰：「汉兴，孝文施大德，天下怀安。至孝景，不复忧异姓，而晁错刻削诸侯，遂使七国同起，合从而西乡。安危之机，岂不以谋哉！」平叛之后，诸侯王唯得衣食租税，汉置相以治国，中央集权乃告完成，西汉二百年宗藩之祸自此消弭。班固赞曰：「汉兴，扫除烦苛，与民休息。至于孝文，加之以恭俭，孝景遵业，率由旧俗。施之以德，移之以礼，黎庶醇厚，几致刑措。」制度之整理与民生之休养二者并举，遂为汉武盛世奠基。",
