    interpretation: "绿林、赤眉之兴亡，实为流民求生之举被天下大势推上政权之争的典型。两军起事，初无图王霸业之心：绿林藏于山中以求活，赤眉涂眉以相识别，所争不过一口粮食。其能倾覆新朝，一则因王莽改制自乱纲纪，币法、田法频更，官吏离心；二则新莽精兵外屯而腹心空虚，昆阳一战，四十二万之众溃于一旦，朝廷威信扫地。其速败亦同出一辙：入长安后，绿林诸将纵兵掠货，赤眉则因三辅饥荒无粮可食，终不能建立有效的赋税与行政体系。刘秀之胜，不在兵多，而在能设官、安民、足食，以政权之力收编群雄。此役另有一层深远影响：关中经两军往来与饥疫，残破不堪，东汉遂定都洛阳，天下重心东移，流民问题自此成为此后王朝施政的镜鉴。",
