    summary: "西汉武帝时司马迁撰，约成于征和二年（公元前91年）。全书一百三十篇、五十二万六千五百字，上起黄帝、下迄汉武帝太初年间，记述约三千年史事，首创本纪、表、书、世家、列传五体结合的纪传体，是中国第一部纪传体通史，亦为二十四史之首。司马迁以「究天人之际，通古今之变，成一家之言」为宗旨，融史料、文学与思想于一炉，奠定中国古代正史的格局与精神。其书藏之名山、传之其人，历两汉魏晋至今，注疏不绝，流布天下，既为史学之宗，亦为文学之圣。",
    background: "汉承秦祚，至武帝时已历七十余年，海内一统，府库充实。武帝罢黜百家、独尊儒术，设五经博士、开立太学；又北击匈奴、通使西域、南平百越，疆宇大开，王朝急需对自古以来的制度沿革与天人秩序作一系统总结。秦火之后，典籍残缺，汉兴百年，书积如山，石室金匮、天禄阁所藏，亟需有人董理编次。司马迁之父司马谈任太史令，学天官于唐都，受《易》于杨何，习道论于黄子，志在续《春秋》而未就；元封元年（公元前110年）临终执司马迁之手，泣论明主贤君忠臣死义之士不可废灭，遗命论著。司马迁二十岁南游江淮，北涉汶泗，后奉使巴蜀、昆明，足迹半天下。元封三年（公元前108年）继任太史令，得尽读石室金匮之书。太初元年（公元前104年）参与制定《太初历》，同时动笔著书。天汉三年（公元前98年）因李陵之祸受宫刑，隐忍发愤，前后历十四年乃成。",
