          "司马迁既殁，其书稍得出。其外孙平通侯杨恽好读《史记》，祖述其书，遂宣布焉，时在汉宣帝之世，去成书已三四十年。然汉廷以其书有微文刺讥、贬损当世之语，观之者多有限制；至汉元帝、成帝间，东平王刘宇上疏求《太史公书》，大司马王凤以为《太史公书》有战国纵横权谲之谋、汉兴之初谋臣奇策，不宜在诸侯王，奏拒之，可见其书传播仍受禁约。",
          "今本《史记》中，十篇有录无书，亡于汉末魏晋之间，相传元帝、成帝间博士褚少孙补《武帝本纪》《三王世家》《龟策列传》等篇。南朝宋裴骃作《史记集解》，唐司马贞作《史记索隐》，唐张守节作《史记正义》，世称「三家注」，与正文并行，遂成定本。此后历代刊刻，若南宋黄善夫本、明代南北监本、清代武英殿本、同治间金陵书局本，流布不绝。今存篇目仍为一百三十篇之数，而字数较五十二万六千五百字之原数略有出入。"
