      {
        heading: "发愤著书，成一家言",
        paragraphs: [
          "征和二年（前91）前后，《太史公书》——即后世所称《史记》——基本完成。全书一百三十篇，五十二万六千五百字，记事上起黄帝，下至汉武帝太初年间，前后约三千年。十二本纪写帝王，十表列时势，八书述制度，三十世家记诸侯，七十列传写各色人物。司马迁自言其志在「究天人之际，通古今之变，成一家之言」。书成之后，「藏之名山，副在京师」，以待后世圣人君子。这部书当时并未公开流传，直到汉宣帝时，经其外孙平通侯杨恽祖述传播，始渐行于世。",
          "《史记》最大的创造，是确立了纪传体。在它之前，史书或记言如《尚书》，或记事如《春秋》，皆以事件或言辞为纲。司马迁以人物为本位，用本纪、世家、列传写人，用书记制度，用表系年月，五种体例互相配合，网罗宏富而条理分明。自此以后，纪传体成为历代正史的标准体裁：班固《汉书》沿之，范晔《后汉书》沿之，历代相承，遂成「二十四史」之统绪，两千年不能出其范围。一部书而能开创一个延续两千年的写作传统，中国文化史上并不多见。",
          "司马迁笔下的人物，常带一股郁勃不平之气。他写项羽兵败垓下，犹作「力拔山兮气盖世」之歌；写李广终身不封侯，引「桃李不言，下自成蹊」之誉；写荆轲刺秦，图穷匕见，绕柱而走；写屈原放逐，行吟泽畔，颜色憔悴。他评判人物，不问成败，不问身份，只问其在历史中的实际作用与精神气节：项羽虽败而列本纪，陈涉虽微而入世家，孔子布衣而居世家。班固称其「文直，其事核，不虚美，不隐恶，故谓之实录」；鲁迅在《汉文学史纲要》中更以「史家之绝唱，无韵之离骚」许之。史笔与文笔，在《史记》中合而为一，唐宋古文家韩愈、柳宗元以下，无不奉为文章典范。"
        ]
      }
