    interpretation: "《史记》的根本变革，在于把「人」放到了历史的中心。《尚书》记言，《春秋》记事，典章与事件是主角；司马迁以本纪、世家、列传写人，把朝代更替还原为具体人物的抉择与命运，既是体裁的革命，也是史观的转折。他评判历史只看实际作用，不问官方名分：项羽败死而列本纪，陈涉首事而入世家，孔子布衣而居世家。这种「不虚美、不隐恶」的实录精神，成为后世正史最高的写作准则。宫刑之祸反而成就了《史记》的深刻：切肤之痛使他对失败者与悲剧人物有强烈共情，笔下常带郁勃不平之气。此后班固沿其体例修《汉书》，历代相承成「二十四史」统绪；其文纵横排宕，又为唐宋古文家所宗。史笔与文笔，自此合流。",
