          "始元六年（前81）春，武与将吏士卒随行者九人得发单于庭。李陵置酒贺武，起舞而歌，泣下数行，与之决别。武等循来时旧路，逾年方至长安。诏武奉一太牢，谒武帝园庙，以告不辱使命。乃拜武为典属国，秩中二千石，主四方蛮夷归义之事；赐钱二百万，公田二顷，宅一区。常惠、徐圣、赵终根皆拜中郎，赐帛各二百匹；其余六人老病归家，赐钱人十万，复其终身。史载「武留匈奴凡十九岁，始以强壮出，及还，须发尽白」。",
