    interpretation: "推恩令之深层，在以制度分解政治。汉初诸侯之患，根于裂土临民、世袭罔替；七国之乱后，景帝虽已收支郡、省王官，然王国大者犹据数郡，与朝廷相持。武帝亲政，外伐匈奴，内虑藩国，而裂土之制不可猝除。其时嫡长子继承制下，诸侯余子无尺寸之封，怨望久蓄，乃离心之阶。推恩令即以「私恩」为名，化此矛盾为皇恩：王分其地予余子，余子为列侯而侯国别属汉郡。于是王失其实土，子获其爵位，朝廷收其郡县，三方各得所欲，而分国之实成。与晁错削地之强夺不同，推恩纯以利诱：不夺一城、不黜一王，齐、赵、梁大邦数世自析；施恩之名由王自请，故天下无怨；析地之实归侯属汉，故王权日削。故史称其为阳谋，垂范百代：唐宋宗王不临民，明制郡王以下层递降爵、岁禄无权，皆推恩之遗意。削藩至此，几于道矣。",
