    interpretation: "卫青之崛起，是汉武帝时代双重变革的缩影。其一为军事变革：汉初对匈奴，以步骑守边、和亲羁縻，始终被动挨打；卫青以骑兵长途奔袭、深入漠北的战法，将战争从边塞推入匈奴腹地，以攻代守，彻底改变汉匈战争的形态。收复河南、置朔方郡，更将军事胜利转化为领土与制度成果，使河套永久纳入汉帝国版图，其影响远超一时一役之胜负。其二为用人变革：卫青以骑奴之身、外戚之进，而能立功绝域、位极人臣，本是汉武帝不拘一格拔擢寒微的范例。然其可贵，在于始终清醒——功高如彼，却深明「人臣奉法遵职而已」，不以养士立威，不以军权干政。汉代外戚自吕氏以来，擅权者多难得善终，卫青是极少的例外。他以谦退换取君权之信任，以战功换取国家之安宁，终以茂陵一冢、阴山之形为一生作结。这种以退为进的政治智慧，比他的骑兵战术更耐人寻味。",
