    summary: "征和二年（公元前91年），汉武帝刘彻晚年多病多疑，疑左右以巫术诅咒。宠臣江充奉命治巫蛊，构陷太子刘据，掘太子宫而得桐木人，逼太子无以自明。七月，太子从少傅石德之计，收斩江充，发兵与丞相刘屈氂战于长安，五日巷战，死者数万。兵败后太子逃亡湖县，被围自刎，卫皇后亦自杀，卫氏宗族几尽。此案牵连伏诛者数万人，西汉政局为之一变。武帝事后悟其冤，族灭江充，作思子宫，并于征和四年下轮台诏痛自反省，汉家政策由武转守，启昭宣中兴之端。",
    background: "汉武帝即位已逾五十年，外击匈奴，内兴功利，海内虚耗。元封四年（公元前107年），关东流民多至二百万口，盗贼蜂起，朝廷遣绣衣使者分部督捕，法禁转苛。晚年武帝年过六旬，多病，常居甘泉宫、建章宫养疾，性情转多疑，恒疑左右以巫蛊诅己。巫蛊即埋木偶人于地下以行诅咒，本属民间巫术，至此忽成政争利器。征和元年（公元前92年），丞相公孙贺捕得京师大侠朱安世，欲赎其子太仆公孙敬声贪墨北军钱之罪。朱安世于狱中反上书，告敬声与武帝女阳石公主私通，且使巫埋木人诅咒。武帝大怒，公孙贺父子死狱中，俱族灭，阳石公主、诸邑公主及故大将军卫青之子卫伉皆坐诛，卫氏外戚势力自此衰落。此案一开巫蛊之狱端，朝野上下遂以告密相倾，构陷成风。",
