      {
        heading: "帝悔悟思子",
        paragraphs: [
          "久之，高寝郎田千秋上书讼冤：「子弄父兵，罪当笞；天子之子过误杀人，当何罪。」言婉而切。武帝览书而悟，叹息称善，即拜田千秋为大鸿胪，数月而拔为丞相。遂族灭江充之家，焚苏文于横桥，夷其党羽。丞相刘屈氂亦坐与贰师将军李广利谋立昌邑王刘髆、祝诅天子，腰斩于市，妻子枭首；李广利时方将兵击匈奴，闻讯降虏，后死于匈奴。至此，构陷太子的主使人尽伏其辜。",
          "武帝怜太子无辜，乃作思子宫，为归来望思台于湖，望之而泣，天下闻而悲之。又遣使祭吊泉鸠里，收葬太子及二孙，务从丰厚。征和四年（公元前89年）六月，御史大夫桑弘羊等奏请增屯田于轮台、渠犁，以张威西域。武帝下诏，深陈既往之悔，尽罢屯田，封田千秋为富民侯，以明休息养民之意，是即轮台诏。汉家政策由武转守，征伐之事自此息肩，海内始得苏息。",
          "后元二年（公元前87年）二月，武帝崩于五柞宫，年七十，幼子刘弗陵立，是为昭帝，大司马大将军霍光、车骑将军金日磾、左将军上官桀、御史大夫桑弘羊受遗诏辅政。霍光为霍去病之弟，卫氏虽败而霍氏继起。元平元年（公元前74年）昭帝崩，昌邑王刘贺立而旋废，戾太子之孙刘病已被迎立为帝，是为宣帝。宣帝即位，追谥祖父刘据为戾太子，奉园邑改葬，恤其遗孤。巫蛊之祸彻底改写了汉武帝晚年的权力格局，亦为昭宣中兴铺平了道路。"
        ]
      }
