    interpretation: "巫蛊之祸的深层，是皇权与外戚、天子与储君之间难以调和的结构性矛盾。卫氏一门外有卫青、霍去病之军功，内有卫皇后之尊，太子刘据又仁厚宽缓，与武帝用法深刻之政见多有不合，朝中遂有宽厚者附太子、深酷者毁之的分野。江充之流不过是火种，真正的干柴是武帝晚年的猜忌与权力高度集中于一人之身的体制。案发之后数万人伏诛、公卿列侯为之一空，说明这不仅仅是一桩冤案，更是一场对卫氏外戚及其政治网络的全面清洗。至于武帝是否有意借刀杀人，史学界向有争议：多数学者认为武帝为奸人所蔽、事后追悔是真；亦有观点认为其晚年政策转向早有谋划，巫蛊之祸客观上为轮台之诏扫清了障碍。无论如何，轮台诏罢兵屯田、与民休息，汉家政策由武转守，终启昭宣中兴，这场惨祸遂成西汉由盛而衰再转安的转折点。",
