          "楚汉相拒于荥阳、成皋前后三年，汉军屡战屡败，屡败而复振，其根本即在关中。萧何转漕关中之粟，由渭河顺流而下，源源供给前线军食；又补发兵员，前后调遣关中丁壮赴军者不计其数。及荥阳危困，萧何更发关中老弱未傅悉诣荥阳，以固守御（《汉书·高帝纪》）。项羽虽勇冠三军，却无后方可恃，粮秣日蹙；刘邦虽屡败，而关中转输不绝。此消彼长之间，胜负实已判于战场之外。",
          "刘邦屯兵前线，屡遣使者还关中慰劳萧何，名为体恤，实含猜嫌。鲍生说萧何曰：「王暴衣露盖，数使使劳苦君者，有疑君心也。为君计，莫若遣君之子孙兄弟昆弟能胜兵者悉诣军门，王必益信君。」萧何从之，刘邦大悦。其后关中事权一归于萧何，计户转漕、给食不乏。萧何镇守关中数年，未尝亲历战阵，却以一相之任，聚天下之粮、拢天下之兵，使刘邦得以专意于前线而无后顾之忧。是以天下既定，论功行赏，刘邦以萧何为第一。"
