    interpretation: "萧何之历史地位，实在于他是「制度的继承者与开创者」。其收秦丞相御史律令图书一事，意义远过一时之收藏：秦以法度并天下，其郡县版籍、律令文书、山川阨塞之记，乃治理庞大帝国的操作手册；萧何收取档案，使汉集团在起事之初即由流寇式的武装转变为掌握全国信息的政治力量。其作《九章律》，摭秦法宜于时者而增损之，既去秦法之苛酷，又存其行政架构，汉室法制由此奠基，萧何由此成为连接秦制与汉制的关键人物。观其镇关中，立法令、立宗庙社稷、计户转漕，所行者皆秦丞相御史之旧务；汉能承秦制而有天下，萧何之功居其大半。功人功狗之论、鄂千秋万世之功之说，所重者是制度经营而非摧锋陷阵。司马迁以「谨守管钥，因民之疾秦法，顺流与之更始」评之，诚为笃论；然其助吕后诛韩信，亦见功臣政治之酷烈，非一人之进退所能解。",
