    interpretation: "盐铁会议表面上是财政政策之辩论，实为三重矛盾交汇：其一，武帝外事征伐、内兴聚敛所留下的制度惯性，与轮台诏后思富养民之政治转向之间的矛盾；其二，霍光与桑弘羊之权力之争；其三，儒家义利、本末之观与国家干预财政之说之争。霍光借文学清议以折桑弘羊之威，却不能尽废官营，因边费国用所系，遂以罢酤留榷收场，此非任何一方之全胜，而是政治妥协。其深远处在于：此后两千年，盐铁榷酤成为王朝财政之永久骨架，而「不与民争利」亦成为久唱不衰之政治原则，两者之张力贯穿帝制时代始终。《盐铁论》以对话之体保存此番交锋，使中国古代第一次大规模经济政策辩论得以完整传世。",
