    summary: "张衡（公元78—139），字平子，南阳郡西鄂县人（今河南南阳北），东汉天文学家、机械家、文学家。安、顺之际两任太史令，元初四年（117）铸浑天仪以象天，阳嘉元年（132）造候风地动仪以测地震方位，著《灵宪》阐浑天之说，言「宇之表无极，宙之端无穷」。辞章亦冠绝当世，《二京赋》精思十年乃成，与司马相如、扬雄、班固并称汉赋四大家；《归田赋》又开抒情小赋之先。晚岁出为河间相，治威严、整法度，上下肃然；征拜尚书，永和四年（139）卒，年六十二。其以一人之身兼擅科学与文学，后世仰为通儒，崔瑗为作墓碑，称其「数术穷天地，制作侔造化」。",
    background: "东汉承平既久，洛阳为天下枢轴。光武帝刘秀以图谶立国，谶纬之学列于学官，中元元年（56）颁布天下，号称内学；天人感应之说笼罩朝野，凡有日蚀、地震、水旱，朝野辄附会以言政，或诿之近习，或归罪三公。然太史令一职掌天文、星历、灾异之记，须以观测推步为凭，与空衍灾祥者不同，遂为实证之学存一脉于庙堂。安帝、顺帝之世，外戚邓氏、梁氏相继专权，宦官渐预政事，地震水旱频仍，士大夫每以灾异上疏言事，而朝政日紊。南阳为帝乡，刘秀发迹于此，号曰南都，文教甲于一方；班固《两都赋》既行，京都大赋成为一时文体之宗，才士争相模拟。张衡生长其间，家世为南阳著姓，祖父张堪官至渔阳太守，政绩卓著；其学出入经术、天文、辞章之间，正应时代之需。",
