          "永元十二年（100）前后，张衡归乡，南阳郡举孝廉，不行；大将军邓骘为外戚之魁，势倾朝野，闻其名，累召不应。时士人多奔走权门，张衡独淡然。班固《两都赋》既行，京都大赋为一时文体之宗，张衡拟其体而作《二京赋》，咏长安、洛阳之壮伟侈靡，终归于节俭戒奢。自下笔至蒇事，精思十年乃成，本传载其「精思傅会，十年乃成」。文辞弘丽，倾动京师，与司马相如、扬雄、班固并称汉赋四大家。"
