          "永和三年（138），张衡视事三年，上书乞骸骨。朝廷不允，征拜尚书。在河间时，张衡感外戚梁商、梁冀之势已成，朝纲日紊，己志不伸，乃作《归田赋》。其辞曰「游都邑以永久，无明略以佐时；徒临川以羡鱼，俟河清乎未期」，思退耕田园，临清流而赋诗。此赋体制短小，情致清丽，一变汉大赋铺陈堆砌之习，开抒情小赋之先，为魏晋以下辞赋别开生面。",
