    interpretation: "张衡之历史地位，要在两重。其一，以观测实证对抗谶纬虚妄。东汉以图谶立国，凡灾异辄附会以言政；张衡居太史之位，独以仪器为准：浑天仪以漏壶转之而与天合，地动仪一丸既发而千里验之——「验之以事，合契若神」，八字正是实证精神之根。其上疏请禁图谶，虽不见用，而骨力自存。其二，以机械之巧开技术一脉。浑象、地动仪，皆以铜铸、以水运、以机发，承先秦技巧之统，启唐宋仪象之制；唐一行、宋苏颂之浑天仪象，其源皆可上溯。至于文学，《二京赋》为京都大赋之巅峰，《归田赋》为抒情小赋之嚆矢，一人而兼两体之极。崔瑗「数术穷天地，制作侔造化」之评，非过誉也。",
