    interpretation: "张骞通西域，其初衷本是军事外交之谋：武帝欲结月氏以断匈奴右臂，张骞之行，实为汉匈百年战争中的一环。然月氏乐居妫水之北，无意东归，其直接目的可谓未达。而其深远后果，则远出庙堂所料：其一，汉始悉西域地理、物产、兵民虚实，其后霍去病取河西、李广利伐大宛、郑吉护西域，皆以张骞所开之知见为基；其二，河西四郡之设与西域都护之立，使汉家统御西及葱岭，开疆拓土至于极边，西域三十六国纳入汉家秩序；其三，使节往还之外，商路随之而开，丝绸、漆器西行，葡萄、苜蓿、汗血马、琉璃东渐，东西文化交融，利及百世。司马迁以「凿空」二字极称其开辟之功，实为定论。张骞两使，十三年留虏，百余人仅二人得还，其坚忍忠信，足为百代使臣之表。",
