    interpretation: "白虎观会议的实质，是皇权对经学解释权的收编。自汉武帝立五经博士，经义定于学官，然章句家法纷争不已，天子之制往往为经师之说所格。石渠、白虎两会，皆以天子亲临称制，裁决五经同异，将最高学术裁判权收归御前。班固撰集之《白虎通义》，遂非寻常经说，而是以经义为名、以谶纬为饰、以制度为体的国家意识形态法典。其收编之径有三：一曰定经本，二曰一异说，三曰立纲纪。三纲六纪之定型，使君臣父子夫妇之伦，从儒家理想化为制度律令，垂之二千年。然谶纬入典，神学附会，终使经学丧失理性思辨之机，转启魏晋玄学之反动。此书之得失，实为帝制时代政学关系之缩影。",
