    interpretation: "西域都护府之设，非一战一役之功，乃六十年层累之果。张骞通使于前，李广利用兵于后，桑弘羊议屯田，郑吉竟其功，每一步皆以前一步为阶。其深层逻辑，在以最小代价维持最大秩序：汉不郡县其地，不编户其民，存诸国君长与其风俗，而以印绶封授定其名分，以质子之制结其心意，以屯田自养省转输之费，以征发诸国兵示赏罚之权。五十余国，户口不过数十万，汉兵不出数千，而号令班于西域，以其得羁縻之宜也。三绝三通之周期，皆系于中原国力之消长与匈奴之兴衰：王莽扰之而绝，光武置之，永平通之，永初又绝，延光再通，无不如此。都护府罢则丝路梗阻，都护府立则商旅畅行，二者相为表里。后世承其制，唐设安西、北庭都护府于龟兹、庭州，清设伊犁将军，名异实同，皆其流衍。",
