          "昭、宣以后，汉家常制未改。元凤元年（前80），桑弘羊与上官桀等谋反伏诛，而盐铁均输之官不废，财计仍统于大司农。宣帝本始、五凤间，对匈奴、西羌用兵及赈济灾荒之费，多取给于此。元帝初元五年（前44）夏四月，尝罢郡国盐铁官及常平仓；永光三年（前41）冬十一月，以用度不足，复盐铁官。东汉初，郡国盐铁官仍沿置；和帝永元元年（89）夏四月，罢盐铁，令民得煮盐、收税。此为官营极大松弛之一节点，然官府榷税之格局未尝尽废，山海之利终不在民。",
          "官营之弊，史不绝书。盐铁会议所载文学之言：县官铁器「苦恶」，价贵于私铸数倍，吏强令民买置；农具不适田作，民用反困。均输平准本为平物价、均贡赋，行之既久，亦或成敛取之具，郡国转以多收为功。王莽时立「六筦」，盐铁居其一，法益苛细，吏缘为奸，地皇中遂至大乱。要之，国用饶给之利与官府作器之弊如影随形：豪商虽抑，而民困未尽除；利权并于一司，则积重难返，此其得中之失。",
