    interpretation: "盐铁官营之深层，在战争财政与国营经济之结合：汉初「藏富于民」之局，由此转向「利归县官」。其利在速效，不增田赋而军兴之费沛然有余，均输平准且平抑物价、裁抑商贾豪强；其弊在结构，官府自产自销，无市价竞争，则器苦恶、价昂贵而强配于民，行政之费转嫁于农户。桑弘羊以商贾任国计，以利权收归中央，开两千年禁榷财政之先路；贤良文学以义利、本末立论，责「与民争利」，成国家干预与放任之争最早一场大规模对辩。二者非全然是非之判：无盐铁则边费无出，存盐铁则民困随生。后世榷盐、盐钞、盐引踵事增华，皆在调处同一矛盾，终未能脱此利弊相随之格局。",
