    interpretation: "班固以一人之身，历私修获狱与奉诏修史两际，正见东汉史权由私门归于朝廷之大势。《汉书》创断代为史之体，以一朝之兴废为限，十二纪、八表、十志、七十传，使典章制度因十志而明，天下图书因《艺文志》而存。自此以后，历代正史皆沿断代之体，与《史记》通史并峙，班马优劣聚讼两千年，范晔评其文赡而事详，刘知几则讥其剽袭旧文；要之，通史断代，各擅其场。《艺文志》承刘歆《七略》，为目录学之祖，使先秦西汉典籍存目于史。然班固虽以史才受知明帝，终因卷入窦氏之祸，死于洛阳令种兢宿怨之手，年六十一而卒，未竟之篇尚待妹昭、马续续成。此结局既见外戚宦官之争的酷烈，亦见当时士人依附权贵的身不由己，其个人命运与制度创制，遂成两汉史学之一体两面。",
