    interpretation: "张仲景在《后汉书》《三国志》中无传，此一事实本身即为重要之历史信息：汉魏之际，医犹方技，士人不以医名世，史官亦不为之立传，故仲景生平仅赖其书自序与医家记载流传。其「医圣」地位并非汉魏所固有，而是宋以后逐渐层累建构而成——北宋校正医书局将其书颁为官定经典，金元注家继之，明清南阳医圣祠之祀典化其圣化过程于制度层面完成，日本汉方古方派之崇奉又自外部加固之。长沙太守、坐堂行医之传说，虽于史无征，却折射出明清社会以士人价值整合医学之深层需要。自建安宗族之殇出发，一部方书终成万世之法，其人之生平愈隐，其书之地位愈显；名与实之间，恰见中国医学经典化之独特路径。",
